using System.Reflection;using TownOfHost;using TownOfHost.Modules;using UnityEngine;
class Program {
 static int passed;static void Check(bool b){if(!b)throw new Exception("assertion failed");}static void Near(float a,float b){Check(Math.Abs(a-b)<.001f);}static void Test(string n,Action a){Setup();a();passed++;Console.WriteLine("PASS "+n);}
 static HudManager H=>HudManager.Instance;
 static void Setup(){HudManager.Instance=new();PlayerControl.LocalPlayer=new();GameStates.IsModHost=true;GameStates.IsLobby=false;GameStates.IsMeeting=false;GameStates.IsInGame=GameStates.IsInTask=true;GameSettingMenu.Instance=false;Options.OptionGameChatSetting=new();NaturalDisasters.IsThisMode=false;RoleGuideButtonPatch._btnRenderer=new();RoleGuideButtonPatch.guideFrameRenderer=new();RoleGuideButtonPatch.guideFrameRenderer.transform.parent=RoleGuideButtonPatch._btnRenderer.transform;RoleGuideButtonPatch.isPanelOpen=false;RoleGuideButtonPatch.CloseCalls=0;H.SettingsButton.transform.localPosition=new(3.8f,2.5f,-1);H.Chat.chatButton.transform.localPosition=new(3.02f,2.5f,-1);H.Chat.chatButton.gameObject.SetActive(false);H.MatchInfoButton.gameObject.SetActive(false);CredentialsPatch.pingTrackerCredentialAspectPos=new();CredentialsPatch.pingTrackerCredential=new();foreach(var field in new[]{"headerPositioning","headerMissingGuideLogged","headerFailureLogged"})typeof(CredentialsPatch).GetField(field,BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,false);typeof(CredentialsPatch).GetField("headerDiagnosticCount",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,0);Logger.Lines.Clear();}
 static void Closed(OptionsMenuBehaviour o=null)=>typeof(GameplayHudVisibilityPatch).GetMethod("OptionsClosed",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{o??H.GameMenu});
 static void NativeClose(){H.GameMenu.Close();H.Chat.chatButton.gameObject.SetActive(true);H.MatchInfoButton.gameObject.SetActive(true);Closed();}
 static void VideoSequence(){RoleGuideButtonPatch.UpdateTopRightButtonLayout();var x=RoleGuideButtonPatch._btnRenderer.transform.localPosition.x;H.GameMenu.IsOpen=true;RoleGuideButtonPatch.UpdateButtonVisibility();NativeClose();Check(!H.Chat.chatButton.gameObject.activeSelf&&!H.MatchInfoButton.gameObject.activeSelf);Near(RoleGuideButtonPatch._btnRenderer.transform.localPosition.x,x);Check(RoleGuideButtonPatch.HasGuideButton);}
 static void Main(string[] args){
 if(args.Contains("--glyph-before-repro")){Setup();ReproduceInkOverflow();return;}
 if(args.Contains("--header-before-repro")){Setup();ReproduceAnchorMismatch();return;}
 if(args.Contains("--before-repro")){Setup();VideoSequence();return;}
 Test("video sequence settings close restores task header",VideoSequence);
 Test("task update removes reactivated chat before laying out HELP",()=>{H.Chat.chatButton.gameObject.SetActive(true);RoleGuideButtonPatch.UpdateTopRightButtonLayout();Check(!H.Chat.chatButton.gameObject.activeSelf);Near(RoleGuideButtonPatch._btnRenderer.transform.localPosition.x,2.6f);});
 Test("repeated twenty settings cycles do not drift or duplicate",()=>{for(int i=0;i<20;i++)VideoSequence();Near(RoleGuideButtonPatch._btnRenderer.transform.localPosition.x,2.6f);});
 Test("policy works before HELP artwork is ready",()=>{RoleGuideButtonPatch._btnRenderer=null;H.Chat.chatButton.gameObject.SetActive(true);H.MatchInfoButton.gameObject.SetActive(true);RoleGuideButtonPatch.UpdateTopRightButtonLayout();Check(!H.Chat.chatButton.gameObject.activeSelf&&!H.MatchInfoButton.gameObject.activeSelf);});
 Test("ghost chat restored after task-state transition",()=>{PlayerControl.LocalPlayer.Data.IsDead=true;GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.activeSelf&&H.Chat.VisibleCalls==1);});
 Test("ghost chat settings close remains usable",()=>{PlayerControl.LocalPlayer.Data.IsDead=true;NativeClose();Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("task chat option remains available",()=>{Options.OptionGameChatSetting.Value=true;GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.activeSelf&&H.Chat.VisibleCalls==1);});
 Test("task chat settings close stays enabled",()=>{Options.OptionGameChatSetting.Value=true;NativeClose();Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("natural-disaster mode does not gain forbidden living chat",()=>{NaturalDisasters.IsThisMode=true;Options.OptionGameChatSetting.Value=true;NativeClose();Check(!H.Chat.chatButton.gameObject.activeSelf);});
 Test("natural-disaster ghost access retained",()=>{NaturalDisasters.IsThisMode=true;PlayerControl.LocalPlayer.Data.IsDead=true;GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("lobby chat remains available and match info unchanged",()=>{GameStates.IsInGame=GameStates.IsInTask=false;GameStates.IsLobby=true;H.MatchInfoButton.gameObject.SetActive(true);RoleGuideButtonPatch.UpdateTopRightButtonLayout();Check(H.Chat.chatButton.gameObject.activeSelf&&H.MatchInfoButton.gameObject.activeSelf);});
 Test("meeting chat remains available",()=>{GameStates.IsMeeting=true;GameStates.IsInTask=false;RoleGuideButtonPatch.UpdateTopRightButtonLayout();Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("return from meeting removes living task chat again",()=>{GameStates.IsMeeting=true;GameStates.IsInTask=false;RoleGuideButtonPatch.UpdateTopRightButtonLayout();GameStates.IsMeeting=false;GameStates.IsInTask=true;RoleGuideButtonPatch.UpdateTopRightButtonLayout();Check(!H.Chat.chatButton.gameObject.activeSelf);});
 Test("non-MOD-host games retain native chat and match information",()=>{GameStates.IsModHost=false;H.Chat.chatButton.gameObject.SetActive(true);H.MatchInfoButton.gameObject.SetActive(true);GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.activeSelf&&H.MatchInfoButton.gameObject.activeSelf);});
 Test("no player is harmless",()=>{PlayerControl.LocalPlayer=null;H.Chat.chatButton.gameObject.SetActive(true);GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("no player data is harmless",()=>{PlayerControl.LocalPlayer.Data=null;GameplayHudVisibilityPatch.Apply(H);});
 Test("disconnected owner does not mutate UI",()=>{PlayerControl.LocalPlayer.Data.Disconnected=true;H.Chat.chatButton.gameObject.SetActive(true);GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("null HUD is harmless",()=>GameplayHudVisibilityPatch.Apply(null));
 Test("inactive HUD does not show ghost chat",()=>{H.gameObject.SetActive(false);PlayerControl.LocalPlayer.Data.IsDead=true;GameplayHudVisibilityPatch.Apply(H);Check(!H.Chat.chatButton.gameObject.activeSelf);});
 Test("no chat controller still handles match info safely",()=>{H.Chat=null;H.MatchInfoButton.gameObject.SetActive(true);GameplayHudVisibilityPatch.Apply(H);Check(!H.MatchInfoButton.gameObject.activeSelf);});
 Test("no chat button is harmless",()=>{H.Chat.chatButton=null;GameplayHudVisibilityPatch.Apply(H);});
 Test("no match-info button is harmless",()=>{H.MatchInfoButton=null;NativeCloseSafe();});
 Test("missing task-chat option uses the safe default",()=>{Options.OptionGameChatSetting=null;H.Chat.chatButton.gameObject.SetActive(true);GameplayHudVisibilityPatch.Apply(H);Check(!H.Chat.chatButton.gameObject.activeSelf);});
 Test("menu without game remains untouched",()=>{GameStates.IsInGame=GameStates.IsInTask=false;H.Chat.chatButton.gameObject.SetActive(true);GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("closing unrelated main-menu settings does not change game header",()=>{H.Chat.chatButton.gameObject.SetActive(true);Closed(new());Check(H.Chat.chatButton.gameObject.activeSelf);});
 Test("closing without a HUD is harmless",()=>{HudManager.Instance=null;Closed(new());});
 Test("HELP hidden while native options are open and restored after close",()=>{H.GameMenu.IsOpen=true;RoleGuideButtonPatch.UpdateButtonVisibility();Check(!RoleGuideButtonPatch.HasGuideButton);H.GameMenu.IsOpen=false;RoleGuideButtonPatch.UpdateButtonVisibility();Check(RoleGuideButtonPatch.HasGuideButton);});
 Test("HELP panel closes when options open",()=>{RoleGuideButtonPatch.isPanelOpen=true;H.GameMenu.IsOpen=true;RoleGuideButtonPatch.UpdateButtonVisibility();Check(RoleGuideButtonPatch.CloseCalls==1&&!RoleGuideButtonPatch.isPanelOpen);});
 Test("game settings visibility rule preserved",()=>{GameSettingMenu.Instance=true;RoleGuideButtonPatch.UpdateButtonVisibility();Check(!RoleGuideButtonPatch.HasGuideButton);GameSettingMenu.Instance=false;RoleGuideButtonPatch.UpdateButtonVisibility();Check(RoleGuideButtonPatch.HasGuideButton);});
 Test("no HUD does not break HELP visibility",()=>{HudManager.Instance=null;RoleGuideButtonPatch.UpdateButtonVisibility();});
 Test("ghost chat is not forced open while options are open",()=>{PlayerControl.LocalPlayer.Data.IsDead=true;H.GameMenu.IsOpen=true;GameplayHudVisibilityPatch.Apply(H);Check(!H.Chat.chatButton.gameObject.activeSelf&&H.Chat.VisibleCalls==0);});
 Test("enabled chat does not repeatedly invoke SetVisible",()=>{Options.OptionGameChatSetting.Value=true;for(int i=0;i<30;i++)GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.VisibleCalls==1);});
 Test("disabled chat does not repeatedly call SetActive",()=>{int n=H.Chat.chatButton.gameObject.Changes;for(int i=0;i<30;i++)GameplayHudVisibilityPatch.Apply(H);Check(H.Chat.chatButton.gameObject.Changes==n);});
 foreach(float ratio in new[]{4f/3,16f/9,21f/9,9f/16})Test("caption right edge stays to the left of HELP at aspect "+ratio,()=>{H.UICamera.aspect=ratio;H.SettingsButton.transform.position=new(H.UICamera.orthographicSize*ratio-.5f,2.5f,-1);H.Chat.chatButton.transform.position=new(H.SettingsButton.transform.position.x-.78f,2.5f,-1);RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();Check(CredentialsPatch.pingTrackerCredentialAspectPos.RightEdge<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("caption follows legitimate chat-visible layout",()=>{Options.OptionGameChatSetting.Value=true;RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();Check(CredentialsPatch.pingTrackerCredentialAspectPos.RightEdge<RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x);});
 Test("unchanged caption geometry does not repeatedly adjust",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();int n=CredentialsPatch.pingTrackerCredentialAspectPos.Adjustments;CredentialsPatch.UpdateCredentialLayout();Check(CredentialsPatch.pingTrackerCredentialAspectPos.Adjustments==n);});
 Test("caption updates immediately when HELP moves",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();float old=CredentialsPatch.pingTrackerCredentialAspectPos.RightEdge;Options.OptionGameChatSetting.Value=true;RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();Check(CredentialsPatch.pingTrackerCredentialAspectPos.RightEdge<old);});
 Test("missing guide frame falls back safely",()=>{RoleGuideButtonPatch.guideFrameRenderer=null;CredentialsPatch.UpdateCredentialLayout();Near(CredentialsPatch.pingTrackerCredentialAspectPos.DistanceFromEdge.x,2.52f);});
 Test("hidden guide does not reserve its frame",()=>{RoleGuideButtonPatch._btnRenderer.gameObject.SetActive(false);CredentialsPatch.UpdateCredentialLayout();Near(CredentialsPatch.pingTrackerCredentialAspectPos.DistanceFromEdge.x,1.8f);});
 Test("non-orthographic camera uses fallback",()=>{H.UICamera.orthographic=false;Check(!RoleGuideButtonPatch.TryGetHeaderRightOffset(out _));});
 Test("missing UI camera uses fallback",()=>{H.UICamera=null;Check(!RoleGuideButtonPatch.TryGetHeaderRightOffset(out _));});
 foreach(float invalid in new[]{0f,-1f,float.NaN,float.PositiveInfinity,float.NegativeInfinity})Test("invalid viewport width rejected "+invalid,()=>Check(!HudHeaderLayout.TryRightOffset(invalid,.5f,out _)));
 foreach(float invalid in new[]{0f,-1f,1f,2f,float.NaN,float.PositiveInfinity,float.NegativeInfinity})Test("invalid guide viewport coordinate rejected "+invalid,()=>Check(!HudHeaderLayout.TryRightOffset(10,invalid,out _)));
 Test("default header offset includes a readable gap",()=>{Check(HudHeaderLayout.TryRightOffset(10,.7f,out float n));Near(n,3.12f);});
 HeaderOverlapTests();
 GlyphTests();
 Console.WriteLine($"RESULT {passed} passed, 0 failed (production HUD policy and extracted UI methods, native substitutes)");
 }

 static float ActualRight(){var a=new Vector3[4];CredentialsPatch.pingTrackerCredential.rectTransform.GetWorldCorners(a);return a.Max(v=>v.x);}
 static void Clamp()=>typeof(CredentialsPatch).GetMethod("KeepHeaderClearOfGuide",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{false});
 static void NativeAdjusted(AspectPosition a)=>typeof(CredentialsPatch).GetNestedType("HeaderAnchorAdjustedPatch",BindingFlags.NonPublic).GetMethod("Postfix",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{a});
 static void ReproduceAnchorMismatch(){RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredentialAspectPos.NativeAnchorBias=.8f;CredentialsPatch.UpdateCredentialLayout();Check(ActualRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);}
 static void HeaderOverlapTests(){
 Test("native anchor mismatch reproducing screenshot is clamped",ReproduceAnchorMismatch);
 Test("native anchor readjustment keeps text outside HELP",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();CredentialsPatch.pingTrackerCredentialAspectPos.NativeAnchorBias=1;CredentialsPatch.pingTrackerCredentialAspectPos.AdjustPosition();NativeAdjusted(CredentialsPatch.pingTrackerCredentialAspectPos);Check(ActualRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("other native anchors are untouched",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.transform.position=new(4,2,3);NativeAdjusted(new AspectPosition());Near(CredentialsPatch.pingTrackerCredential.transform.position.x,4);});
 Test("clamp has no accumulated position drift",()=>{ReproduceAnchorMismatch();float x=CredentialsPatch.pingTrackerCredential.transform.position.x;for(int i=0;i<100;i++)Clamp();Near(CredentialsPatch.pingTrackerCredential.transform.position.x,x);});
 Test("clamp preserves vertical position and drawing depth",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.transform.position=new(4,2.3f,-17);Clamp();Near(CredentialsPatch.pingTrackerCredential.transform.position.y,2.3f);Near(CredentialsPatch.pingTrackerCredential.transform.position.z,-17);});
 Test("actual rectangle offset is measured instead of text pivot",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.rectTransform.RightBias=.7f;CredentialsPatch.pingTrackerCredential.transform.position=new(3,0,0);Clamp();Check(ActualRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("already clear text is not moved",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.transform.position=new(-2,0,0);Clamp();Near(CredentialsPatch.pingTrackerCredential.transform.position.x,-2);});
 Test("hidden text is not repositioned",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.transform.position=new(4,0,0);CredentialsPatch.pingTrackerCredential.gameObject.SetActive(false);Clamp();Near(CredentialsPatch.pingTrackerCredential.transform.position.x,4);});
 Test("hidden HELP does not constrain text",()=>{RoleGuideButtonPatch._btnRenderer.gameObject.SetActive(false);CredentialsPatch.pingTrackerCredential.transform.position=new(4,0,0);Clamp();Near(CredentialsPatch.pingTrackerCredential.transform.position.x,4);});
 Test("missing HELP frame is safe",()=>{RoleGuideButtonPatch.guideFrameRenderer=null;CredentialsPatch.pingTrackerCredential.transform.position=new(4,0,0);Clamp();Near(CredentialsPatch.pingTrackerCredential.transform.position.x,4);});
 Test("missing credential text is safe",()=>{CredentialsPatch.pingTrackerCredential=null;Clamp();});
 Test("overlap correction works without UI camera projection",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();H.UICamera=null;CredentialsPatch.pingTrackerCredential.transform.position=new(4,0,0);Clamp();Check(ActualRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("changing window geometry remeasures real frame",()=>{ReproduceAnchorMismatch();H.UICamera.aspect=4f/3;H.SettingsButton.transform.position=new(3.3f,2.5f,-1);RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredentialAspectPos.AdjustPosition();NativeAdjusted(CredentialsPatch.pingTrackerCredentialAspectPos);Check(ActualRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("native aspect-ratio overload applies the same text-only correction",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.transform.position=new(4,2,-17);typeof(CredentialsPatch).GetNestedType("HeaderAnchorAspectAdjustedPatch",BindingFlags.NonPublic).GetMethod("Postfix",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{CredentialsPatch.pingTrackerCredentialAspectPos});Check(ActualRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("native aspect-ratio overload ignores other text anchors",()=>{CredentialsPatch.pingTrackerCredential.transform.position=new(4,2,-17);typeof(CredentialsPatch).GetNestedType("HeaderAnchorAspectAdjustedPatch",BindingFlags.NonPublic).GetMethod("Postfix",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{new AspectPosition()});Near(CredentialsPatch.pingTrackerCredential.transform.position.x,4);});
 Test("left shift computes just the overlap and gap",()=>Near(HudHeaderLayout.RequiredLeftShift(2.5f,2),.62f));
 Test("left shift is zero when already clear",()=>Near(HudHeaderLayout.RequiredLeftShift(1.5f,2),0));
 foreach(float invalid in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity})Test("invalid actual text coordinate ignored "+invalid,()=>Near(HudHeaderLayout.RequiredLeftShift(invalid,2),0));
 foreach(float invalid in new[]{float.NaN,float.PositiveInfinity,float.NegativeInfinity})Test("invalid actual guide coordinate ignored "+invalid,()=>Near(HudHeaderLayout.RequiredLeftShift(2,invalid),0));
 }

 static void LateHeader()=>typeof(CredentialsPatch).GetMethod("HeaderLateLayout",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);
 static float InkRight()=>ActualRight()+CredentialsPatch.pingTrackerCredential.InkOverflow;
 static void ReproduceInkOverflow(){RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.InkOverflow=.9f;CredentialsPatch.UpdateCredentialLayout();Check(InkRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);}
 static void GlyphTests(){
 Test("visible glyphs outside the rectangle cannot overlap HELP",ReproduceInkOverflow);
 Test("late mesh rebuild handles text assigned after early positioning",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();CredentialsPatch.pingTrackerCredential.PendingInkOverflow=1.1f;LateHeader();Check(InkRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f&&CredentialsPatch.pingTrackerCredential.MeshUpdates==1);});
 Test("late correction follows a native anchor update later in the frame",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.UpdateCredentialLayout();CredentialsPatch.pingTrackerCredentialAspectPos.NativeAnchorBias=.9f;CredentialsPatch.pingTrackerCredentialAspectPos.AdjustPosition();CredentialsPatch.pingTrackerCredential.PendingInkOverflow=.8f;LateHeader();Check(InkRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("late correction preserves vertical position and depth",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.transform.position=new(4,2,-17);CredentialsPatch.pingTrackerCredential.PendingInkOverflow=1;LateHeader();Near(CredentialsPatch.pingTrackerCredential.transform.position.y,2);Near(CredentialsPatch.pingTrackerCredential.transform.position.z,-17);});
 Test("native font rebuild reentry does not recurse",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.PendingInkOverflow=1;CredentialsPatch.pingTrackerCredential.DuringMeshUpdate=()=>NativeAdjusted(CredentialsPatch.pingTrackerCredentialAspectPos);LateHeader();Check(CredentialsPatch.pingTrackerCredential.MeshUpdates==1&&InkRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("late correction does not accumulate drift",()=>{ReproduceInkOverflow();float x=CredentialsPatch.pingTrackerCredential.transform.position.x;for(int i=0;i<100;i++)LateHeader();Near(CredentialsPatch.pingTrackerCredential.transform.position.x,x);});
 Test("late diagnostics have a strict three-event bound",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();for(int i=0;i<50;i++)LateHeader();Check(Logger.Lines.Count==3&&Logger.Lines.All(x=>x.StartsWith("HEADER_LAYOUT_V3 rect=")));});
 Test("missing guide emits only one fixed diagnostic",()=>{RoleGuideButtonPatch.guideFrameRenderer=null;for(int i=0;i<50;i++)LateHeader();Check(Logger.Lines.Count==1&&Logger.Lines[0]=="HEADER_LAYOUT_V3_NO_GUIDE");});
 Test("temporary font failure does not interrupt HUD and can recover",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.FailMesh=true;LateHeader();LateHeader();Check(Logger.Lines.Count(x=>x=="HEADER_LAYOUT_V3_DEFERRED")==1);CredentialsPatch.pingTrackerCredential.FailMesh=false;CredentialsPatch.pingTrackerCredential.PendingInkOverflow=.8f;LateHeader();Check(InkRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 Test("ordinary update does not force repeated mesh rebuilds",()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();for(int i=0;i<20;i++)CredentialsPatch.UpdateCredentialLayout();Check(CredentialsPatch.pingTrackerCredential.MeshUpdates==0);});
 foreach(float overflow in new[]{.1f,.5f,1.5f,2.5f})Test("late glyph extent accounted for at overflow "+overflow,()=>{RoleGuideButtonPatch.UpdateTopRightButtonLayout();CredentialsPatch.pingTrackerCredential.PendingInkOverflow=overflow;LateHeader();Check(InkRight()<=RoleGuideButtonPatch.guideFrameRenderer.bounds.min.x-.119f);});
 }
 static void NativeCloseSafe(){GameplayHudVisibilityPatch.Apply(H);}
}
